<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$proposals=$db->query("SELECT p.*,l.name,l.email,(SELECT id FROM invoices i WHERE i.proposal_id=p.id LIMIT 1) invoice_id FROM proposals p JOIN leads l ON l.id=p.lead_id ORDER BY p.created_at DESC")->fetchAll();function money($v,$c){return $c.' '.number_format((float)$v,2);}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proposals & Quotations</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1250px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Proposals & Quotations</h1><p class="text-muted mb-0">Create, send and track client proposals.</p></div><a class="btn btn-dark" href="proposal-form.php">+ New Proposal</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Proposal</th><th>Client</th><th>Total</th><th>Valid Until</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($proposals as $p):?><tr><td><strong><?=$esc($p['proposal_number'])?></strong><div class="small text-muted"><?=$esc($p['title'])?></div></td><td><?=$esc($p['name'])?><div class="small text-muted"><?=$esc($p['email'])?></div></td><td><?=money($p['total'],$p['currency'])?></td><td><?=$esc($p['valid_until']?:'—')?></td><td><span class="badge text-bg-secondary"><?=ucfirst($esc($p['status']))?></span></td><td><a class="btn btn-sm btn-outline-dark" href="proposal-form.php?id=<?=$p['id']?>">Edit</a> <a target="_blank" class="btn btn-sm btn-outline-primary" href="proposal-view.php?token=<?=$esc($p['public_token'])?>">View</a> <a target="_blank" class="btn btn-sm btn-outline-secondary" href="proposal-pdf.php?token=<?=$esc($p['public_token'])?>">PDF</a> <?php if($p['status']==='accepted'):?><?php if($p['invoice_id']):?><a class="btn btn-sm btn-success" href="invoice-view.php?token=<?=$esc($db->query('SELECT public_token FROM invoices WHERE id='.(int)$p['invoice_id'])->fetchColumn())?>">Invoice</a><?php else:?><a class="btn btn-sm btn-primary" href="invoice-from-proposal.php?proposal_id=<?=$p['id']?>">Create Invoice</a><?php endif;?><?php endif;?></td></tr><?php endforeach;?><?php if(!$proposals):?><tr><td colspan="6" class="p-4 text-muted">No proposals created yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>